/* Big Knobs, Key Lights and the remote presses (FM-1 Big Screen 1.3.23 on): the app turns the knobs (04 e n), sets
 * MASTER (06 lo hi), presses buttons and keys (07 id down); the lit and glowing buttons and keys go to it (05). They
 * go in through fm1-base's own remote (plat_fm1.c: remote.btn / keys / enc / master), the path tools/fm1_remote.py
 * takes, so Erik37 sees them as the player's hands. Our ids: buttons 0 OCT- 1 OCT+ 2 FX .. 13 REC, keys 14 + k. */
static uint32_t bs_btn, bs_keys;                 /* what the app holds down (let go when it stops asking) */
static uint32_t bs_lit_b, bs_lit_k, bs_dim_b;    /* the lights as plat_leds set them (our ids) */
static inline uint32_t bs_b_of(uint32_t id) { return id >= 2u ? id - 2u : 12u + id; }   /* our id -> B_* */
static inline uint32_t bs_id_of(uint32_t b) { return b >= 12u ? b - 12u : b + 2u; }     /* B_* -> our id */
void bs_lights(uint32_t buttons, uint32_t keys, uint32_t dim)   /* plat_fm1.c plat_leds */
{
    uint32_t b, lb = 0, db = 0;
    for (b = 0; b < NB; b++) {
        if (buttons >> b & 1u)
            lb |= 1u << bs_id_of(b);
        else if (dim >> b & 1u)
            db |= 1u << bs_id_of(b);
    }
    bs_lit_b = lb;
    bs_dim_b = db;
    bs_lit_k = keys;
}

/* the velocity of key k from the probe's peak since the press, 0 when there is no reading: t_lo = 1,
 * t_hi = 127, with t_curve between (or the driven keys' curve). 2026-10-15, played on every key: the
 * probe cannot tell a light press (8 counts above a bare touch, against the direct reading's ~200), so
 * it stays for the top row only, at 0 / 43 / 2.40 (the user's choice). Measured
 * (Velo notes/01-lab.md, DRIVE 2): any contact lifts the probe ~20, a light press 27..36, a firm one
 * piles up at 43..45 (the weak driver's current limit); with 20..48 the lightest press read ~35 and
 * nothing reached 127, so the ends sit at the clusters: 27 and 44 */
static uint8_t sense_probe_velocity(uint32_t t)
{
    uint32_t lo = sn_cfg.t_lo, hi = sn_cfg.t_hi > sn_cfg.t_lo ? sn_cfg.t_hi : sn_cfg.t_lo + 1u, pk;
    float top = (float)(sn_cfg.vmax ? sn_cfg.vmax : 1u), c, x;
    if (t >= SN_NKEYS || !sn_probe[t].down)
        return 0;
    pk = sn_probe[t].peak;
    if (pk <= lo)
        return 1;
    if (pk >= hi)
        return (uint8_t)top;
    c = (float)(sn_cfg.t_curve ? sn_cfg.t_curve : sn_cfg.d_curve ? sn_cfg.d_curve : 1u) * 0.01f;
    x = (float)(pk - lo) / (float)(hi - lo);
    return (uint8_t)(1.0f + (top - 1.0f) * fm_powf(x, c) + 0.5f);
}

void app_say(const char *a, const char *b)
{
    uint32_t i;
    char t[48];
    for (i = 0; i < 23u && a && a[i]; i++)
        ui.msg[0][i] = a[i];
    ui.msg[0][i] = 0;
    for (i = 0; i < 23u && b && b[i]; i++)
        ui.msg[1][i] = b[i];
    ui.msg[1][i] = 0;
    ui.msg_until = plat_ms() + 1300u;
    ui.head_q = -1;
    if (ann_on()) {
        t[0] = 0;
        cat_s(t, ui.msg[0]);
        if (ui.msg[1][0]) {
            cat_s(t, " ");
            cat_s(t, ui.msg[1]);
        }
        ann_say(t, 0, ANN_NOW);
    }
}

/* the inside (gold plate, strings) and the lid, its edge and the prop (boot.py top_layers) */
static void top_layers(float ang, int mirror)
{
    static v3 q[NPLAN];
    float c = fcos_(ang), s = fsin_(ang), th = 0.012f;
    int i, k;
    for (i = 0; i < NPLAN; i++)
        q[i] = V(plan[i][0], Y_CASE1 - 0.002f, plan[i][1]);
    poly3(q, NPLAN, C3(6, 6, 8), mirror, -20, 1, 1.0f, 0);
    if (ang > 0.02f) {
        for (i = 0; i < NPLAN; i++)
            q[i] = V(plan[i][0] * 0.97f + 0.012f, Y_CASE1 - 0.01f, plan[i][1] * 0.94f + BD * 0.03f);
        poly3(q, NPLAN, mixc(GOLD_DEEP, GOLD_DIM, 0.2f), mirror, -21, 1, 1.0f, 0);
        for (k = 0; k < 12; k++) {             /* strings: lines from the keyboard to the bridge */
            float z = BD * (0.08f + 0.84f * k / 11.0f), xe = 0.3f;
            v3 l2[2];
            if (z > BD * 0.05f) {
                float mx = 0;
                for (i = 0; i < NBENT; i++)
                    if (plan[i][1] * 0.94f + BD * 0.03f <= z + 0.02f && plan[i][0] > mx)
                        mx = plan[i][0];
                xe = mx * 0.92f;
            }
            l2[0] = V(0.03f, Y_CASE1 - 0.008f, z);
            l2[1] = V(xe, Y_CASE1 - 0.008f, z);
            poly3(l2, 2, STEEL, mirror, -22, 1, 0.28f, 1);
        }
    }
    for (i = 0; i < NPLAN; i++) {
        b_lidtop[i] = lid_point(plan[i][0], Y_LID + th, plan[i][1], c, s);
        b_lidbot[i] = lid_point(plan[i][0], Y_LID, plan[i][1], c, s);
    }
    for (i = 0; i < NPLAN - 1; i++)
        quad(b_lidbot[i], b_lidbot[i + 1], b_lidtop[i + 1], b_lidtop[i], C3(20, 20, 24), mirror, -30, 1);
    b_under = ang * 57.29578f > 21.0f + 0.5f;  /* past the camera's pitch we see the underside */
    {
        v3 n = b_under ? V(0, -c, s) : V(0, c, -s);
        poly3(b_under ? b_lidbot : b_lidtop, NPLAN, shade(n, b_under ? C3(34, 31, 28) : LACQ1, 1.0f, 6), mirror, -31, 1, 1.0f, 0);
    }
    if (ang > 0.25f) {                         /* the prop stick */
        v3 l2[2] = {{0.56f, Y_CASE1, BD * 0.30f}, lid_point(0.56f, Y_LID, BD * 0.36f, c, s)};
        poly3(l2, 2, GOLD_DIM, mirror, -32, 1, 1.0f, 1);
    }
}

static const erk_glyph *glyph_of(const erk_font *f, uint32_t ch)
{
    int lo = 0, hi = f->n - 1;
    while (lo <= hi) {
        int m = (lo + hi) >> 1;
        if (f->g[m].ch == ch)
            return &f->g[m];
        if (f->g[m].ch < ch)
            lo = m + 1;
        else
            hi = m - 1;
    }
    return 0;
}

/* the string's characters: '\x7f' a middle dot, '\x80' an en dash */
static float twidth(const erk_font *f, const char *s, float track)
{
    float w = 0;
    int n = 0;
    for (; *s; s++, n++) {
        const erk_glyph *g = glyph_of(f, (uint8_t)*s);
        w += g ? g->adv / 16.0f : f->px * 0.3f;
    }
    return w + (n > 1 ? track * (n - 1) : 0);
}

/* a rounded rectangle as a polygon (the corners in 4 steps) */
static int rrect_pts(float *p, float x0, float y0, float x1, float y1, float r)
{
    static const float C[5] = {1.0f, 0.9239f, 0.7071f, 0.3827f, 0.0f};
    int n = 0, i, q;
    float cx[4] = {x1 - r, x0 + r, x0 + r, x1 - r}, cy[4] = {y0 + r, y0 + r, y1 - r, y1 - r};
    for (q = 0; q < 4; q++)
        for (i = 0; i < 5; i++) {
            float c = C[i], s = C[4 - i], dx, dy;
            switch (q) {
            case 0: dx = c; dy = -s; break;
            case 1: dx = -s; dy = -c; break;
            case 2: dx = -c; dy = s; break;
            default: dx = s; dy = c; break;
            }
            p[2 * n] = cx[q] + dx * r;
            p[2 * n + 1] = cy[q] + dy * r;
            n++;
        }
    return n;
}

void app_frame(void)
{
    input();
#ifdef ERIK_BIG_SCREEN
    bs_service();
#endif
    if (ui.state == ST_BOOT) {
        uint32_t t = plat_ms() - ui.boot_t0;
        int f = (int)(t / BOOT_MS);
        if (f >= BOOT_FRAMES + 12) {          /* the last frame held ~0.8 s */
            ui.state = ST_RUN;
            ui.full = 1;
        } else {
            if (f >= BOOT_FRAMES)
                f = BOOT_FRAMES - 1;
            if (f != ui.boot_frame) {
                ui.boot_frame = f;
                boot_step(f);
                flush();
            }
            return;
        }
    }
    draw_page();
}

/* bits i0 .. i1-1 of w (msb first) into the 595; the outputs stay as they are until fm1__sr_latch */
static void fm1__sr_bits(uint32_t w, uint32_t i0, uint32_t i1)
{
    uint32_t i;
    /* read-modify-write per edge on purpose: write-only edges were too short for the
     * 595 on the board and latched the neighbouring column (LEDs and keys copied one column over) */
    for (i = i0; i < i1; i++) {
        if (w & (0x8000u >> i))
            FM1_PR(FM1_PA, FM1_OUT) |= 1u << 4;
        else
            FM1_PR(FM1_PA, FM1_OUT) &= ~(1u << 4);
        FM1_PR(FM1_PA, FM1_OUT) |= 1u << 3;
        FM1_PR(FM1_PA, FM1_OUT) &= ~(1u << 3);
    }
}

static void release(voice *v)
{
    uint32_t g;
    if (v->flags & F_NODAMP) {
        v->state = V_RING;                            /* no damper: rings on at its decay */
        return;
    }
    v->state = V_REL;
    v->m = v->mr1;
    v->rblocks = 0;
    /* damper noise: louder for loud, still-ringing notes */
    g = (uint32_t)gain_of(v);                         /* Q15 */
    g = ((uint32_t)st.rel_level * (9830u + ((22937u * isqrt(g << 15)) >> 15))) >> 15;
    g = (g * isqrt((uint32_t)v->amp << 15)) >> 15;
    noise(v->key, g);
}

void erk_init(const erk_bank *b, const erk_cfg *c)
{
    int i;
    int16_t *p = res_buf;
    bk = b;
    cfg = *c;
    memset(vc, 0, sizeof vc);
    pad_reset();
    memset(res_buf, 0, sizeof res_buf);
    bend_q16 = 65536;
    for (i = 0; i < NRES; i++) {
        res_c[i].ln = p;
        res_c[i].len = res_len[i];
        res_c[i].pos = 0;
        res_c[i].lp = 0;
        res_c[i].g = 0;
        p += res_len[i];
    }
    st.rev_type = cfg.reverb;
    st.rev_mix = cfg.rev_mix;
    st.res_level = cfg.res_level;
    st.rel_level = cfg.rel_level;
    st.master = cfg.master;
    rev_apply();
    st.rev_dirty = 0;
#if ERK_MODAL
    erkm_init();
#endif
    sus = soft = sost = 0;
    sus_lvl = soft_lvl = 0;
    send = send_t = 0;
    ped = 0;
    m_half = 1u << 30;
    erk_sost_keys[0] = erk_sost_keys[1] = erk_sost_keys[2] = 0;
}
